const float dim = .25;

vec3 boxSize = vec3(.95*dim,.95*dim,.95*dim);
vec3 frameSize = vec3(dim,dim,dim);

struct sdfData
{
    float closest;
    float dist;
};

sdfData SDF(vec3 p, vec2 cellID, float tt){

   sdfData sdf;
   float minVal_Box = 1E20;
   float minVal_Frame = 1E20;

   float yTop = round(6. * hash12(cellID));
   float yBot = round(6. * hash12(2.43 * cellID));
   float cellOff = hash12(cellID);
   tt = fract(tt + cellOff);

   float bWidth = 2. * dim;
   float gapDelta = 9. * bWidth;

   vec3 motion;
   if (p.y < 0.){
     // Bottom boxes
     motion = vec3(0., tt * bWidth, 0.);
     for(float y = 0.; y <= yBot; y++){

       vec3 offset = -vec3(0.,(gapDelta + dim) - y * bWidth,0.);
       minVal_Box = min(minVal_Box,sdBox(p - offset + motion, boxSize));
       minVal_Frame = min(minVal_Frame,sdBoxFrame(p - offset + motion, frameSize, .008));     
     }
   }
   else {
     // Top Boxes
     motion = vec3(0., tt * bWidth, 0.);
     for (float y = 0.; y <= yTop-1.; y++){
       motion = vec3(0., tt * bWidth, 0.);
       vec3 offset = vec3(0.,(gapDelta - dim) - y * bWidth,0.);
       minVal_Box = min(minVal_Box,sdBox(p - offset + motion, boxSize));
       minVal_Frame = min(minVal_Frame,sdBoxFrame(p - offset + motion, frameSize, .008));
     }
   }

   // Moving Box
   motion = vec3(0., tt * tt * (2. * gapDelta - (yTop + yBot) * bWidth),0.); 
   vec3 offset = vec3(0.,(gapDelta - dim) - yTop * bWidth,0.);
   minVal_Box = min(minVal_Box,sdBox(p - offset + motion, boxSize));
   minVal_Frame = min(minVal_Frame,sdBoxFrame(p - offset + motion, frameSize, .008));

   sdf.dist += step(0., minVal_Frame - minVal_Box) * (-sdf.dist + minVal_Box);
   sdf.dist += step(0., minVal_Box - minVal_Frame) * (-sdf.dist + minVal_Frame);
   sdf.closest = step(0., minVal_Box - minVal_Frame);

   return sdf;

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   vec2 uv = ( fragCoord - .5* iResolution.xy ) /iResolution.y;
   vec3 col = vec3(0.);   


  // Blur Parameters (samples == 1.0 for no blur)
  float samples = 1.0;
  float spacingFactor = .01;

  vec3 result = vec3(0.);
  float fracTime = fract(.2*iTime);
  // Loop Over the number of samples
  for(float sa = 0.; sa < samples; sa++)
  {
    float tt = fracTime + sa*spacingFactor/samples;

    vec3 camPos = vec3(0., 0., 4.5); 
    vec3 rayDir = normalize(vec3(uv, -1)); 

    float depth = 0.0;

    vec3 p = vec3(0);
    float closest;
    sdfData sdf;

    for(int numIter = 0; numIter < 60; numIter++){
      p = camPos + depth * rayDir;

      p.yz *= rotation(-PI/6.);
      p.xz *= rotation(-PI/4.7);
      p.xy *= rotation(-PI/6.5);


     // Domain Repetition
      vec2 cellID = floor(p.xz);
      p.xz = fract(p.xz) - .5;

      float minVal = 1E20;
      float nReach = 1.;
      for(float xx = -nReach; xx <= nReach; xx++)
      for(float zz = -nReach; zz <= nReach; zz++){
      vec2 cID = cellID + vec2(xx,zz);  
      sdf = SDF(p - vec3(xx,0.,zz), -cID, tt); 

      if (sdf.dist < minVal){
        minVal = sdf.dist;
        closest = sdf.closest;
      }
    }

    depth += minVal;
    if (minVal < .005 || depth > 15.0) break;
  }

  // closest == 1 for edge, 0 for box
  col = closest * vec3(60. * pow(1. - depth/30.,12.) * (3.5-abs(p.y)));

  // Add each sample into the into the result
  result += col;   

  }

  // Divide the results by the number of samples
  vec3 colOut = result*1.0/samples;

  fragColor = vec4(colOut,1.0);
}

#define rotation(angle) mat2(cos(angle), -sin(angle), sin(angle), cos(angle));

float PI = 3.14159;
float TAU = 2.*3.14159;

// Thanks IQ for the SDF functions!
// This version of the Box Frame function was faster than the other from here:
// https://www.shadertoy.com/view/3ljcRh
float dot2( in vec3 v ) { return dot(v,v); }
float sdBoxFrame( vec3 p, vec3 b, float e )
{
       p = abs(p  )-b;
  vec3 q = abs(p+e)-e;

  return sqrt(min(min(dot2(max(vec3(p.x,q.y,q.z),0.0)),
                      dot2(max(vec3(q.x,p.y,q.z),0.0))),
                      dot2(max(vec3(q.x,q.y,p.z),0.0)))) 
         +min(0.0,min(min( max(p.x,max(q.y,q.z)),
                           max(p.y,max(q.z,q.x))),
                           max(p.z,max(q.x,q.y))));
}

float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

// https://www.shadertoy.com/view/4djSRW
float hash12(vec2 p)
{
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}
